using System.ComponentModel.DataAnnotations;
using System.Security.Cryptography;
using System.Text.RegularExpressions;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using TuTuc.Data;
using TuTuc.Models;
namespace TuTuc.Services;
public class AccountManager(AppDbContext db,PrivateDocumentStore documents,IDataProtectionProvider protection,ILogger<AccountManager> log) {
 readonly PasswordHasher<Account> hasher=new();readonly ITimeLimitedDataProtector deactivate=protection.CreateProtector("TuTuc.Account.Deactivate.v1").ToTimeLimitedDataProtector();
 public static string NormalizePhone(string? raw){var p=new string((raw??"").Where(c=>!char.IsWhiteSpace(c)&&c!='-'&&c!='('&&c!=')').ToArray());if(p.StartsWith("+84"))p="0"+p[3..];else if(p.StartsWith("0084"))p="0"+p[4..];return p;}
 static bool PhoneValid(string p)=>Regex.IsMatch(p,@"^0\d{9,10}$");
 static bool ValidPassword(string? p)=>!string.IsNullOrEmpty(p)&&p.Length>=8&&p.Length<=100&&p.Any(char.IsLetter)&&p.Any(char.IsDigit);
 static string InputError(object input){var errors=new List<ValidationResult>();Validator.TryValidateObject(input,new ValidationContext(input),errors,true);return string.Join(" ",errors.Select(x=>x.ErrorMessage));}
 public async Task<Account?> Authenticate(string? email,string? password){if(string.IsNullOrWhiteSpace(email)||string.IsNullOrEmpty(password)||email.Length>200||password.Length>100)return null;var identity=email.Trim().ToLowerInvariant();var phone=NormalizePhone(identity);var user=await db.Accounts.SingleOrDefaultAsync(x=>x.Email==identity||x.Phone!=""&&x.Phone==phone);if(user is null||!user.IsActive)return null;var verified=hasher.VerifyHashedPassword(user,user.PasswordHash,password);if(verified==PasswordVerificationResult.Failed)return null;if(verified==PasswordVerificationResult.SuccessRehashNeeded){user.PasswordHash=hasher.HashPassword(user,password);await db.SaveChangesAsync();}return user;}
 public async Task<(Account? User,string Error)> Register(RegisterInput input){
 var invalid=InputError(input);if(invalid.Length>0)return(null,invalid);if(input.Role is not ("Traveler" or "Provider"))return(null,"Loại tài khoản không hợp lệ.");var email=input.Email.Trim().ToLowerInvariant();var phone=NormalizePhone(input.Phone);if(!PhoneValid(phone))return(null,"Số điện thoại cần dạng 0 và 9–10 chữ số tiếp theo.");if(!ValidPassword(input.Password)||input.Password.Contains(email,StringComparison.OrdinalIgnoreCase))return(null,"Mật khẩu cần 8–100 ký tự, gồm chữ và số, không chứa email.");if(await db.Accounts.AnyAsync(x=>x.Email==email||x.Phone==phone))return(null,"Email hoặc số điện thoại đã được sử dụng.");
 if(input.Role=="Provider"&&!PhoneValid(NormalizePhone(input.ContactPhone)))return(null,"Số điện thoại liên hệ cơ sở không hợp lệ.");var staged=new List<PrivateDocument>();if(input.Role=="Provider"){var upload=await documents.StageAsync(0,"Verification",input.Files);if(upload.Error.Length>0)return(null,upload.Error);staged=upload.Documents;}
 await using var tx=await db.Database.BeginTransactionAsync();try{
 var user=new Account{Name=input.Name.Trim(),Email=email,Phone=phone,Role=input.Role,VerificationStatus=input.Role=="Provider"?"Chờ xác minh":"",ProviderStatus=null,ProviderVerified=false};user.PasswordHash=hasher.HashPassword(user,input.Password);db.Accounts.Add(user);await db.SaveChangesAsync();db.UserProfiles.Add(new UserProfile{OwnerId=user.Id});
 if(input.Role=="Provider"){db.ProviderProfiles.Add(new ProviderProfile{OwnerId=user.Id,CompanyName=input.CompanyName!.Trim(),CompanyType=input.CompanyType!.Trim(),ContactName=input.ContactName!.Trim(),Address=input.Address!.Trim(),ContactPhone=NormalizePhone(input.ContactPhone),ContactEmail=input.ContactEmail!.Trim().ToLowerInvariant()});var dossier=new VerificationDossier{OwnerId=user.Id,Content=input.DossierContent!.Trim(),Representative=input.Representative!.Trim()};db.VerificationDossiers.Add(dossier);await db.SaveChangesAsync();db.DossierSubmissions.Add(new DossierSubmission{DossierId=dossier.Id,Submission=0,Content=dossier.Content,Representative=dossier.Representative,SubmittedAt=dossier.SubmittedAt});foreach(var d in staged){d.OwnerId=user.Id;d.ObjectId=dossier.Id;}db.PrivateDocuments.AddRange(staged);var adminIds=await db.Accounts.Where(x=>x.Role=="Admin"&&x.IsActive).Select(x=>x.Id).ToListAsync();foreach(var admin in adminIds)db.Notifications.Add(new UserNotification{OwnerId=admin,Title="Hồ sơ nhà cung cấp mới",Description=input.CompanyName,Url=$"/Verification/Details/{dossier.Id}"});}
 db.AuditEntries.Add(new AuditEntry{ActorId=user.Id,Entity="Account",EntityId=user.Id.ToString(),Action="Đăng ký tài khoản"});await db.SaveChangesAsync();await tx.CommitAsync();return(user,"");
 }catch(Exception e)when(e is DbUpdateException or InvalidOperationException){await tx.RollbackAsync();documents.CleanupFiles(staged);log.LogError(e,"Đăng ký chưa thể hoàn tất.");return(null,"Chưa thể tạo tài khoản. Email hoặc số điện thoại có thể đã được dùng; vui lòng kiểm tra và gửi lại.");}}
 public Task<Account?> Find(int id)=>db.Accounts.SingleOrDefaultAsync(x=>x.Id==id&&x.IsActive);
 public async Task<ProfilePageVm?> Profile(int id){var user=await Find(id);if(user is null)return null;var profile=await db.UserProfiles.SingleOrDefaultAsync(x=>x.OwnerId==id)??new UserProfile{OwnerId=id};var provider=await db.ProviderProfiles.SingleOrDefaultAsync(x=>x.OwnerId==id);return new ProfilePageVm{Account=user,Profile=profile,Provider=provider,Input=new ProfileInput{Name=user.Name,Phone=user.Phone,Bio=user.Bio,Residence=profile.Residence,Interests=profile.Interests,SharingScope=profile.SharingScope,ShareContact=profile.ShareContact,Version=Convert.ToBase64String(user.Version),ProviderVersion=provider is null?null:Convert.ToBase64String(provider.Version),ContactName=provider?.ContactName,Address=provider?.Address,ContactPhone=provider?.ContactPhone,ContactEmail=provider?.ContactEmail}};}
 public async Task<string> UpdateProfile(int id,ProfileInput input){var invalid=InputError(input);if(invalid.Length>0)return invalid;if(input.SharingScope is not ("Public" or "Registered" or "Connected" or "Private"))return "Phạm vi chia sẻ không hợp lệ.";var user=await Find(id);if(user is null)return "Không tìm thấy tài khoản đang hoạt động.";if(!TryVersion(input.Version,out var expected))return "Phiên bản hồ sơ không hợp lệ. Hãy tải lại.";var phone=NormalizePhone(input.Phone);if(phone.Length>0&&!PhoneValid(phone))return "Số điện thoại chưa hợp lệ.";if(phone.Length>0&&await db.Accounts.AnyAsync(x=>x.Id!=id&&x.Phone==phone))return "Số điện thoại đã được sử dụng.";
 var provider=await db.ProviderProfiles.SingleOrDefaultAsync(x=>x.OwnerId==id);byte[] providerExpected=[];if(user.Role=="Provider"&&provider is not null){if(!TryVersion(input.ProviderVersion,out providerExpected))return "Hãy tải lại hồ sơ cơ sở.";if(string.IsNullOrWhiteSpace(input.ContactName)||string.IsNullOrWhiteSpace(input.Address)||string.IsNullOrWhiteSpace(input.ContactEmail)||!PhoneValid(NormalizePhone(input.ContactPhone)))return "Nhà cung cấp cần đủ người liên hệ, địa chỉ, email và số điện thoại hợp lệ.";}
 var staged=new List<PrivateDocument>();if(input.Avatar is not null){var upload=await documents.StageAsync(id,"Avatar",[input.Avatar]);if(upload.Error.Length>0)return upload.Error;staged=upload.Documents;}
 PrivateDocument? oldAvatar=null;await using var tx=await db.Database.BeginTransactionAsync();try{db.Entry(user).Property(x=>x.Version).OriginalValue=expected;user.Name=input.Name.Trim();user.Phone=phone;user.Bio=(input.Bio??"").Trim();db.Entry(user).Property(x=>x.Name).IsModified=true;var profile=await db.UserProfiles.SingleOrDefaultAsync(x=>x.OwnerId==id);if(profile is null){profile=new UserProfile{OwnerId=id};db.UserProfiles.Add(profile);}profile.Residence=(input.Residence??"").Trim();profile.Interests=(input.Interests??"").Trim();profile.SharingScope=input.SharingScope;profile.ShareContact=input.ShareContact;profile.UpdatedAt=DateTime.UtcNow;
 if(staged.Count>0){oldAvatar=profile.AvatarDocumentId is int old?await db.PrivateDocuments.SingleOrDefaultAsync(x=>x.Id==old&&x.OwnerId==id&&x.Scope=="Avatar"):null;db.PrivateDocuments.AddRange(staged);await db.SaveChangesAsync();profile.AvatarDocumentId=staged[0].Id;if(oldAvatar is not null)db.PrivateDocuments.Remove(oldAvatar);}
 if(provider is not null){db.Entry(provider).Property(x=>x.Version).OriginalValue=providerExpected;provider.ContactName=input.ContactName!.Trim();provider.Address=input.Address!.Trim();provider.ContactPhone=NormalizePhone(input.ContactPhone);provider.ContactEmail=input.ContactEmail!.Trim().ToLowerInvariant();db.Entry(provider).Property(x=>x.ContactName).IsModified=true;}
 await db.SaveChangesAsync();await tx.CommitAsync();if(oldAvatar is not null)documents.CleanupFiles([oldAvatar]);return "";}catch(DbUpdateConcurrencyException){await tx.RollbackAsync();documents.CleanupFiles(staged);return "Hồ sơ vừa được cập nhật ở phiên khác. Hãy tải lại trước khi lưu.";}catch(DbUpdateException e){await tx.RollbackAsync();documents.CleanupFiles(staged);log.LogError(e,"Không thể cập nhật hồ sơ.");return "Chưa thể lưu hồ sơ; số điện thoại có thể đã được dùng.";}}
 public async Task<string> ChangePassword(int id,PasswordInput input){var invalid=InputError(input);if(invalid.Length>0)return invalid;var user=await Find(id);if(user is null)return "Không tìm thấy tài khoản.";if(hasher.VerifyHashedPassword(user,user.PasswordHash,input.CurrentPassword??"")==PasswordVerificationResult.Failed)return "Mật khẩu hiện tại không đúng.";if(!ValidPassword(input.NewPassword)||input.NewPassword.Contains(user.Email,StringComparison.OrdinalIgnoreCase))return "Mật khẩu mới cần 8–100 ký tự, chữ và số, không chứa email.";user.PasswordHash=hasher.HashPassword(user,input.NewPassword);user.SessionStamp=Guid.NewGuid().ToString("N");await db.SaveChangesAsync();return "";}
 public async Task<(DeactivationPage? Page,string Error)> PreviewDeactivation(int id,string? password){var user=await Find(id);if(user is null||user.Role is not ("Traveler" or "Provider"))return(null,"Chức năng này dành cho chủ tài khoản khách hoặc nhà cung cấp.");if(hasher.VerifyHashedPassword(user,user.PasswordHash,password??"")==PasswordVerificationResult.Failed)return(null,"Xác thực lại không thành công.");var page=await BuildDeactivation(user);if(page.Obligations.Count==0){page.Token=deactivate.Protect($"{id}|{user.SessionStamp}",TimeSpan.FromMinutes(5));page.Version=Convert.ToBase64String(user.Version);}return(page,"");}
 public async Task<DeactivationPage> BuildDeactivation(Account user){var id=user.Id;var page=new DeactivationPage();if(user.Role is not ("Traveler" or "Provider")){page.Obligations.Add(new(){Text="Tài khoản quản trị không ngừng qua chức năng dành cho khách/nhà cung cấp.",Url="/Account/Profile"});return page;}
 var bookings=await db.Bookings.Where(x=>x.OwnerId==id||x.TravelService!.OwnerId==id).ToListAsync();foreach(var b in bookings.Where(x=>x.Status is "Chờ xác nhận" or "Chờ phản hồi" or "Đề xuất khác" or "Chờ NCC xác nhận cuối" or "Chờ kiểm tra" or "Chưa chốt"||x.Status=="Đã xác nhận"))page.Obligations.Add(new(){Text=$"Yêu cầu dịch vụ #{b.Id}: {b.Status}. Cần hoàn tất hoặc xử lý đổi/hủy.",Url=user.Role=="Provider"?"/Provider/Requests":"/Marketplace/Requests"});
 var ids=bookings.Select(x=>x.Id).ToArray();if(await db.BookingItemResults.AnyAsync(x=>ids.Contains(x.BookingId)&&x.VerificationStatus=="Chờ kiểm tra"))page.Obligations.Add(new(){Text="Có kết quả dịch vụ đang chờ kiểm tra hoặc đối chiếu.",Url=user.Role=="Provider"?"/Provider/Requests":"/Marketplace/Requests"});if(await db.BookingChanges.AnyAsync(x=>ids.Contains(x.BookingId)&&(x.Status=="Chờ phản hồi"||x.Status=="Đề xuất khác")))page.Obligations.Add(new(){Text="Có đề nghị điều chỉnh/hủy dịch vụ đang chờ phản hồi.",Url=user.Role=="Provider"?"/Provider/Requests":"/Marketplace/Requests"});
 var connections=await db.Connections.Where(c=>c.SenderId==id||db.Companions.Any(d=>d.Id==c.CompanionId&&d.OwnerId==id)).ToListAsync();var connectionIds=connections.Select(x=>x.Id).ToArray();if(await db.CompanionAgreements.AnyAsync(a=>connectionIds.Contains(a.ConnectionId)&&a.Status=="Đã xác nhận"))page.Obligations.Add(new(){Text="Có thỏa thuận đồng hành đang hiệu lực. Hãy rút hoặc cùng ngừng trước.",Url="/Community/Dashboard"});page.Connections=connections.Count(x=>x.Status=="Chờ phản hồi");page.Demands=await db.Companions.CountAsync(x=>x.OwnerId==id&&x.IsPublished);page.Services=await db.Services.CountAsync(x=>x.OwnerId==id&&x.IsAccepting);return page;}
 public async Task<string> Deactivate(int id,string? token,string? version){var user=await Find(id);if(user is null)return "Không tìm thấy tài khoản.";string contents;try{contents=deactivate.Unprotect(token??"");}catch(Exception e)when(e is CryptographicException or FormatException or ArgumentException){return "Phiên xác nhận đã hết hạn hoặc không hợp lệ. Vui lòng xác thực lại.";}if(contents!=$"{id}|{user.SessionStamp}"||!TryVersion(version,out var expected))return "Phiên xác nhận không hợp lệ. Vui lòng xác thực lại.";
 await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);try{await db.Entry(user).ReloadAsync();if(!user.IsActive||contents!=$"{id}|{user.SessionStamp}"||!user.Version.SequenceEqual(expected))return "Tài khoản vừa thay đổi. Vui lòng xác thực lại.";var state=await BuildDeactivation(user);if(state.Obligations.Count>0)return "Vừa phát sinh nghĩa vụ cần xử lý. Tài khoản vẫn hoạt động; vui lòng kiểm tra lại.";
 var connections=await db.Connections.Where(c=>c.SenderId==id||db.Companions.Any(d=>d.Id==c.CompanionId&&d.OwnerId==id)).ToListAsync();var expiring=connections.Where(x=>x.Status=="Chờ phản hồi").ToList();foreach(var c in expiring)c.Status="Hết hiệu lực";var connectionIds=connections.Select(x=>x.Id).ToArray();var proposals=await db.CompanionAgreements.Where(a=>connectionIds.Contains(a.ConnectionId)&&a.Status=="Chờ xác nhận").ToListAsync();foreach(var a in proposals)a.Status="Đã thay thế";
 foreach(var c in expiring){var owner=await db.Companions.Where(x=>x.Id==c.CompanionId).Select(x=>x.OwnerId).SingleAsync();foreach(var recipient in new[]{owner,c.SenderId}.Where(x=>x!=id).Distinct())db.Notifications.Add(new UserNotification{OwnerId=recipient,Title="Đề nghị đồng hành hết hiệu lực",Description="Một bên đã ngừng sử dụng tài khoản. Đề nghị chưa xác nhận không còn hiệu lực.",Url="/Community/Dashboard"});}
 user.IsActive=false;user.SessionStamp=Guid.NewGuid().ToString("N");await db.Companions.Where(x=>x.OwnerId==id).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.IsPublished,false));await db.Services.Where(x=>x.OwnerId==id).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.IsAccepting,false));await db.SaveChangesAsync();await tx.CommitAsync();return "";}catch(DbUpdateConcurrencyException){await tx.RollbackAsync();return "Tài khoản vừa thay đổi. Vui lòng xác thực lại.";}catch(Exception e)when(e is DbUpdateException or InvalidOperationException){await tx.RollbackAsync();log.LogError(e,"Không thể ngừng đồng bộ tài khoản {Id}",id);return "Không thể cập nhật đồng bộ. Tài khoản vẫn hoạt động; vui lòng thử lại.";}}
 public static bool TryVersion(string? value,out byte[] bytes){bytes=[];try{bytes=Convert.FromBase64String(value??"");return bytes.Length==8;}catch(FormatException){return false;}}
}



